import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) return;
        Deque<Long> st = new ArrayDeque<>();
        long sum = 0;
        for (String raw : line.split(",")) {
            String op = raw.trim();
            if (op.isEmpty()) continue;
            if (op.equals("+")) {
                long a = st.pop();
                long b = st.pop();
                st.push(b);
                st.push(a);
                st.push(a + b);
                sum += a + b;
            } else if (op.equals("D")) {
                long d = st.peek() * 2;
                st.push(d);
                sum += d;
            } else if (op.equals("C")) {
                sum -= st.pop();
            } else {
                long v = Long.parseLong(op);
                st.push(v);
                sum += v;
            }
        }
        System.out.println(sum);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) return;
        Deque<Long> q = new ArrayDeque<>();
        StringBuilder sb = new StringBuilder();
        for (String raw : line.split(",")) {
            String token = raw.trim();
            if (token.isEmpty()) continue;
            long t = Long.parseLong(token);
            q.addLast(t);
            while (q.peekFirst() < t - 3000) q.pollFirst();
            if (sb.length() > 0) sb.append(',');
            sb.append(q.size());
        }
        System.out.println(sb.toString());
    }
}

