public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String path = br.readLine();
        if (path == null) return;
        List<String> st = new ArrayList<>();
        for (String part : path.split("/")) {
            if (part.isEmpty() || part.equals(".")) continue;
            if (part.equals("..")) {
                if (!st.isEmpty()) st.remove(st.size() - 1);
            } else {
                st.add(part);
            }
        }
        StringBuilder sb = new StringBuilder();
        for (String part : st) sb.append('/').append(part);
        if (sb.length() == 0) sb.append('/');
        System.out.println(sb.toString());
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) return;
        String body = line.trim();
        if (body.startsWith("[")) body = body.substring(1);
        if (body.endsWith("]")) body = body.substring(0, body.length() - 1);
        body = body.trim();
        int[] temps;
        if (body.isEmpty()) {
            temps = new int[0];
        } else {
            String[] parts = body.split(",");
            temps = new int[parts.length];
            for (int i = 0; i < parts.length; i++) temps[i] = Integer.parseInt(parts[i].trim());
        }
        int n = temps.length;
        int[] res = new int[n];
        Deque<Integer> st = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            while (!st.isEmpty() && temps[i] > temps[st.peek()]) {
                int j = st.pop();
                res[j] = i - j;
            }
            st.push(i);
        }
        StringBuilder sb = new StringBuilder("[");
        for (int i = 0; i < n; i++) {
            if (i > 0) sb.append(',');
            sb.append(res[i]);
        }
        sb.append(']');
        System.out.println(sb.toString());
    }
}

