        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) return;
        line = line.trim();
        int sep = line.indexOf(';');
        String num = line.substring(0, sep).trim();
        int k = Integer.parseInt(line.substring(sep + 1).trim());
        StringBuilder st = new StringBuilder();
        int remove = k;
        for (int i = 0; i < num.length(); i++) {
            char c = num.charAt(i);
            while (remove > 0 && st.length() > 0 && st.charAt(st.length() - 1) > c) {
                st.deleteCharAt(st.length() - 1);
                remove--;
            }
            st.append(c);
        }
        while (remove > 0 && st.length() > 0) {
            st.deleteCharAt(st.length() - 1);
            remove--;
        }
        int idx = 0;
        while (idx < st.length() && st.charAt(idx) == '0') idx++;
        String result = st.substring(idx);
        if (result.isEmpty()) result = "0";
        System.out.println(result);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) return;
        line = line.trim();
        int sep = line.indexOf(';');
        String body = line.substring(0, sep).trim();
        int k = Integer.parseInt(line.substring(sep + 1).trim());
        if (body.startsWith("[")) body = body.substring(1);
        if (body.endsWith("]")) body = body.substring(0, body.length() - 1);
        body = body.trim();
        int[] nums;
        if (body.isEmpty()) {
            nums = new int[0];
        } else {
            String[] parts = body.split(",");
            nums = new int[parts.length];
            for (int i = 0; i < parts.length; i++) nums[i] = Integer.parseInt(parts[i].trim());
        }
        int n = nums.length;
        Deque<Integer> dq = new ArrayDeque<>();
        StringBuilder sb = new StringBuilder("[");
        boolean first = true;
        for (int i = 0; i < n; i++) {
            while (!dq.isEmpty() && nums[dq.peekLast()] <= nums[i]) dq.pollLast();
            dq.addLast(i);
            if (dq.peekFirst() <= i - k) dq.pollFirst();
            if (i >= k - 1) {
                if (!first) sb.append(',');
                sb.append(nums[dq.peekFirst()]);
                first = false;
            }
        }
        sb.append(']');
        System.out.println(sb.toString());
    }
}
